@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  --bg-main: oklch(19.5% 0.029 261.6); /* #0D1B2A */
  --bg-surface: oklch(26.6% 0.032 260.6); /* #1B2838 */
  --bg-surface-hover: oklch(34.8% 0.035 260.6);
  --primary: oklch(29.1% 0.08 266.3); /* #15295A */
  --accent-teal: oklch(68.5% 0.125 236.4); /* #00B4D8 */
  --accent-blue: oklch(50.8% 0.116 250.7); /* #0077B6 */
  --accent-green: oklch(74.6% 0.154 139.6); /* #6CC24A */
  --text-main: oklch(96.3% 0.005 260); /* #F3F4F6 */
  --text-muted: oklch(71.4% 0.015 260); /* #9CA3AF */
  --border: oklch(36.1% 0.018 260.6); /* #3C424B */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-teal);
  text-decoration: none;
  transition: color 0.2s ease;
}
a:hover {
  color: var(--text-main);
}

ul {
  list-style: none;
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

section {
  padding: 6rem 0;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
  margin-bottom: 1rem;
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; }

p {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

/* Buttons */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border-radius: 0.25rem;
  font-weight: 500;
  text-align: center;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.btn-primary {
  background-color: var(--accent-blue);
  color: oklch(98% 0.01 260);
}
.btn-primary:hover {
  background-color: var(--accent-teal);
  color: var(--bg-main);
}

.btn-outline {
  background: transparent;
  color: var(--text-main);
  border: 1px solid var(--border);
}
.btn-outline:hover {
  border-color: var(--accent-teal);
  color: var(--accent-teal);
}

/* Header & Nav */
header {
  position: sticky;
  top: 0;
  background-color: color-mix(in oklch, var(--bg-main) 90%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  z-index: 100;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}
.logo span {
  color: var(--accent-teal);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-item {
  position: relative;
}

.nav-link {
  color: var(--text-muted);
  font-weight: 500;
}
.nav-link:hover, .nav-link.active {
  color: var(--text-main);
}

.dropdown-content {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  background-color: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  min-width: 200px;
  padding: 0.5rem 0;
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  flex-direction: column;
}
.nav-item:hover .dropdown-content {
  display: flex;
}
.dropdown-item {
  padding: 0.75rem 1.5rem;
  color: var(--text-muted);
}
.dropdown-item:hover {
  background-color: var(--bg-surface-hover);
  color: var(--text-main);
}

/* Hero Section */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
}
.hero h1 {
  max-width: 900px;
  margin: 0 auto 1.5rem;
}
.hero p {
  font-size: 1.25rem;
  max-width: 700px;
  margin: 0 auto 2.5rem;
}
.hero-btns {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Cards Grid */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  padding: 2rem;
  transition: transform 0.2s ease, border-color 0.2s;
  cursor: pointer;
}
.card:hover {
  transform: translateY(-5px);
  border-color: var(--accent-teal);
}

/* Diagrams */
.diagram-container {
  background-color: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  padding: 3rem;
  margin: 3rem 0;
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  justify-content: center;
  align-items: center;
}
.diagram-node {
  background-color: var(--bg-main);
  border: 1px solid var(--accent-blue);
  padding: 1.5rem;
  border-radius: 0.5rem;
  text-align: center;
  min-width: 200px;
  position: relative;
}
.diagram-node::after {
  content: '→';
  position: absolute;
  right: -1.5rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--accent-teal);
  font-size: 1.5rem;
}
.diagram-node:last-child::after {
  display: none;
}

/* Tabs */
.tabs-header {
  display: flex;
  gap: 1rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
  overflow-x: auto;
}
.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  padding: 1rem 1.5rem;
  font-size: 1rem;
  font-weight: 500;
  cursor: pointer;
  border-bottom: 2px solid transparent;
}
.tab-btn:hover {
  color: var(--text-main);
}
.tab-btn.active {
  color: var(--accent-teal);
  border-bottom-color: var(--accent-teal);
}
.tab-content {
  display: none;
  animation: fadeIn 0.3s ease;
}
.tab-content.active {
  display: block;
}

/* Accordion */
.accordion {
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  overflow: hidden;
}
.accordion-item {
  border-bottom: 1px solid var(--border);
}
.accordion-item:last-child {
  border-bottom: none;
}
.accordion-header {
  width: 100%;
  text-align: left;
  background: var(--bg-surface);
  border: none;
  padding: 1.5rem;
  color: var(--text-main);
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.accordion-header::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--accent-teal);
}
.accordion-item.active .accordion-header::after {
  content: '-';
}
.accordion-content {
  padding: 0 1.5rem;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  background-color: var(--bg-main);
}
.accordion-item.active .accordion-content {
  padding: 1.5rem;
  max-height: 500px;
}

/* Stats */
.stats-grid {
  display: flex;
  justify-content: center;
  gap: 4rem;
  flex-wrap: wrap;
  text-align: center;
}
.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.stat-circle {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  border: 4px solid var(--accent-teal);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 1rem;
  box-shadow: 0 0 20px rgba(0, 180, 216, 0.2);
}

/* Timeline */
.timeline {
  max-width: 800px;
  margin: 0 auto;
}
.timeline-item {
  margin-bottom: 2rem;
}
.timeline-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}
.timeline-time {
  font-weight: 700;
  color: var(--accent-teal);
}
.timeline-bar-bg {
  height: 10px;
  background-color: var(--bg-surface);
  border-radius: 5px;
  overflow: hidden;
}
.timeline-bar-fill {
  height: 100%;
  background-color: var(--accent-blue);
  border-radius: 5px;
}

/* Carousel */
.carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
  background: var(--bg-surface);
  padding: 3rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
}
.testimonial-slide {
  display: none;
  font-size: 1.25rem;
  font-style: italic;
}
.testimonial-slide.active {
  display: block;
}
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}
.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--border);
  cursor: pointer;
}
.dot.active {
  background: var(--accent-teal);
}

/* Forms */
.form-group {
  margin-bottom: 1.5rem;
}
label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
}
input, select, textarea {
  width: 100%;
  padding: 0.75rem;
  background-color: var(--bg-surface);
  border: 1px solid var(--border);
  color: var(--text-main);
  border-radius: 0.25rem;
  font-family: var(--font-sans);
}
input:focus, select:focus, textarea:focus {
  outline: none;
  border-color: var(--accent-teal);
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
@media (max-width: 768px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--bg-surface);
  padding: 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 1000;
}
.cookie-banner.hidden {
  display: none;
}
.cookie-btns {
  display: flex;
  gap: 1rem;
}

/* Footer */
footer {
  background-color: var(--bg-surface);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  color: var(--text-main);
  margin-bottom: 1.5rem;
}
.footer-col ul li {
  margin-bottom: 0.75rem;
}
.footer-col ul li a {
  color: var(--text-muted);
}
.footer-col ul li a:hover {
  color: var(--accent-teal);
}
.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Utilities */
.text-center { text-align: center; }
.mb-2 { margin-bottom: 2rem; }
.mt-2 { margin-top: 2rem; }
.bg-surface { background-color: var(--bg-surface); }
.py-section { padding: 6rem 0; }

document.addEventListener('DOMContentLoaded', () => {
  // Tabs functionality
  const tabContainers = document.querySelectorAll('.tabs-container');
  tabContainers.forEach(container => {
    const tabBtns = container.querySelectorAll('.tab-btn');
    const tabContents = container.querySelectorAll('.tab-content');

    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class from all buttons and contents in this container
        tabBtns.forEach(b => b.classList.remove('active'));
        tabContents.forEach(c => c.classList.remove('active'));

        // Add active class to clicked button and corresponding content
        btn.classList.add('active');
        const targetId = btn.getAttribute('data-target');
        container.querySelector(`#${targetId}`).classList.add('active');
      });
    });
  });

  // Accordion functionality
  const accordionItems = document.querySelectorAll('.accordion-item');
  accordionItems.forEach(item => {
    const header = item.querySelector('.accordion-header');
    header.addEventListener('click', () => {
      // Check if current item is active
      const isActive = item.classList.contains('active');

      // Close all items
      accordionItems.forEach(i => i.classList.remove('active'));

      // If it wasn't active, open it
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Testimonial Carousel
  const carousel = document.querySelector('.carousel');
  if (carousel) {
    const slides = carousel.querySelectorAll('.testimonial-slide');
    const dots = carousel.querySelectorAll('.dot');

    dots.forEach((dot, index) => {
      dot.addEventListener('click', () => {
        slides.forEach(s => s.classList.remove('active'));
        dots.forEach(d => d.classList.remove('active'));

        slides[index].classList.add('active');
        dot.classList.add('active');
      });
    });
  }

  // Demo Form Validation
  const demoForm = document.getElementById('demo-form');
  if (demoForm) {
    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();

      // Basic validation
      const requiredFields = demoForm.querySelectorAll('[required]');
      let isValid = true;

      requiredFields.forEach(field => {
        if (!field.value.trim()) {
          isValid = false;
          field.style.borderColor = 'red';
        } else {
          field.style.borderColor = 'var(--border)';
        }
      });

      if (isValid) {
        alert('Thank you! Your demo request has been submitted.');
        demoForm.reset();
      } else {
        alert('Please fill out all required fields.');
      }
    });
  }

  // Cookie Banner
  const cookieBanner = document.getElementById('cookie-banner');
  if (cookieBanner) {
    const acceptBtn = document.getElementById('cookie-accept');
    const declineBtn = document.getElementById('cookie-decline');

    // Check if already dismissed
    if (localStorage.getItem('cookieConsent')) {
      cookieBanner.classList.add('hidden');
    }

    const dismissBanner = (val) => {
      localStorage.setItem('cookieConsent', val);
      cookieBanner.classList.add('hidden');
    };

    acceptBtn.addEventListener('click', () => dismissBanner('accepted'));
    declineBtn.addEventListener('click', () => dismissBanner('declined'));
  }
});
